function main(): void {
  const a = Buffer.alloc(5, 'ab');
  const b = Buffer.alloc(4, 7);
  const c = Buffer.alloc(6, Buffer.from('xyz'));
  const d = Buffer.alloc(4, 'aGk=', 'base64');
  const e = Buffer.alloc(3, 'ff', 'hex');
  const f = Buffer.alloc(3);
  console.log(a.toString(), b.join(','), c.toString(), d.toString('hex'), e.toString('hex'), f.join(','));
}
